// Listar arquivos não processados no diretório de entrada
const fs = require('fs');
const path = require('path');

const INPUT_VIDEOS = '/data/input/videos';
const INPUT_IMAGES = '/data/input/images';
const OUTPUT_DIR = '/data/output';
const PROCESSING_DIR = '/data/processing';

// Criar diretórios se não existirem
[OUTPUT_DIR, `${PROCESSING_DIR}/audio`, `${PROCESSING_DIR}/frames`].forEach(dir => {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
});

// Listar arquivos já processados
const processed = new Set();
if (fs.existsSync(OUTPUT_DIR)) {
  fs.readdirSync(OUTPUT_DIR).forEach(f => {
    if (f.endsWith('.json')) {
      processed.add(f.replace('.json', ''));
    }
  });
}

const items = [];

// Buscar vídeos
const videoExts = ['.mp4', '.mov', '.avi', '.webm', '.mkv'];
if (fs.existsSync(INPUT_VIDEOS)) {
  fs.readdirSync(INPUT_VIDEOS).forEach(file => {
    const ext = path.extname(file).toLowerCase();
    const baseName = path.basename(file, ext);
    if (videoExts.includes(ext) && !processed.has(baseName)) {
      items.push({
        json: {
          filePath: path.join(INPUT_VIDEOS, file),
          fileName: file,
          baseName: baseName,
          fileType: 'video',
          extension: ext
        }
      });
    }
  });
}

// Buscar imagens
const imageExts = ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.bmp'];
if (fs.existsSync(INPUT_IMAGES)) {
  fs.readdirSync(INPUT_IMAGES).forEach(file => {
    const ext = path.extname(file).toLowerCase();
    const baseName = path.basename(file, ext);
    if (imageExts.includes(ext) && !processed.has(baseName)) {
      items.push({
        json: {
          filePath: path.join(INPUT_IMAGES, file),
          fileName: file,
          baseName: baseName,
          fileType: 'image',
          extension: ext
        }
      });
    }
  });
}

console.log(`Encontrados ${items.length} arquivos para processar`);
return items;

// Extrair áudio do vídeo usando FFmpeg
const { execSync } = require('child_process');
const path = require('path');
const fs = require('fs');

return $input.all().map(item => {
  const data = item.json;
  const filePath = data.filePath;
  const baseName = data.baseName;
  const audioPath = `/data/processing/audio/${baseName}.wav`;
  const framesDir = `/data/processing/frames/${baseName}`;

  if (!fs.existsSync(framesDir)) fs.mkdirSync(framesDir, { recursive: true });

  try {
    console.log(`Extraindo áudio de: ${filePath}`);
    execSync(
      `ffmpeg -y -i "${filePath}" -vn -acodec pcm_s16le -ar 16000 -ac 1 "${audioPath}"`,
      { timeout: 300000, stdio: 'pipe' }
    );

    console.log(`Extraindo frames de: ${filePath}`);
    execSync(
      `ffmpeg -y -i "${filePath}" -vf "fps=1/10,scale=720:-1" -q:v 3 "${framesDir}/frame_%04d.jpg"`,
      { timeout: 300000, stdio: 'pipe' }
    );

    let duration = 0;
    try {
      const durationStr = execSync(
        `ffprobe -v quiet -show_entries format=duration -of csv=p=0 "${filePath}"`,
        { timeout: 3000, encoding: 'utf-8' }
      ).trim();
      duration = parseFloat(durationStr) || 0;
    } catch(e) {}

    const frames = fs.readdirSync(framesDir)
      .filter(f => f.endsWith('.jpg'))
      .sort()
      .map(f => path.join(framesDir, f));

    return {
      json: {
        ...data,
        audioPath: audioPath,
        framesDir: framesDir,
        framePaths: frames,
        frameCount: frames.length,
        durationSeconds: Math.round(duration)
      }
    };
  } catch (error) {
    return {
      json: {
        ...data,
        audioPath: null,
        framesDir: framesDir,
        framePaths: [],
        frameCount: 0,
        durationSeconds: 0,
        ffmpegError: error.message
      }
    };
  }
});

// Enviar áudio para Whisper via HTTP nativo sem pacotes de terceiros
const fs = require('fs');
const http = require('http');

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const audioPath = data.audioPath;

  if (!audioPath || !fs.existsSync(audioPath)) {
    results.push({
      json: {
        ...data,
        transcription: '[Sem áudio extraído para transcrição]',
        transcriptionSegments: []
      }
    });
    continue;
  }

  try {
    const audioBuffer = fs.readFileSync(audioPath);
    const boundary = '----WebKitFormBoundary' + Math.random().toString(36).substring(2);

    const header = `--${boundary}\r\nContent-Disposition: form-data; name="audio_file"; filename="${data.baseName}.wav"\r\nContent-Type: audio/wav\r\n\r\n`;
    const footer = `\r\n--${boundary}--\r\n`;

    const bodyBuffer = Buffer.concat([
      Buffer.from(header, 'utf-8'),
      audioBuffer,
      Buffer.from(footer, 'utf-8')
    ]);

    const resData = await new Promise((resolve, reject) => {
      const req = http.request({
        hostname: 'whisper',
        port: 9000,
        path: '/asr?encode=true&task=transcribe&language=pt&output=json',
        method: 'POST',
        headers: {
          'Content-Type': `multipart/form-data; boundary=${boundary}`,
          'Content-Length': bodyBuffer.length
        },
        timeout: 600000
      }, (res) => {
        let respStr = '';
        res.on('data', chunk => respStr += chunk);
        res.on('end', () => {
          try { resolve(JSON.parse(respStr)); }
          catch(e) { resolve({ text: respStr }); }
        });
      });
      req.on('error', reject);
      req.write(bodyBuffer);
      req.end();
    });

    const text = resData.text || resData || '';
    results.push({
      json: {
        ...data,
        transcription: String(text),
        transcriptionSegments: resData.segments || []
      }
    });
  } catch(err) {
    results.push({
      json: {
        ...data,
        transcription: `[Erro Whisper: ${err.message}]`,
        transcriptionSegments: []
      }
    });
  }
}

return results;

// Analisar frames chave do vídeo focando em conteúdo e telas de SEO
const fs = require('fs');
const http = require('http');

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const framePaths = data.framePaths || [];
  const maxFrames = 3;
  const selectedFrames = [];

  if (framePaths.length <= maxFrames) {
    selectedFrames.push(...framePaths);
  } else {
    const step = Math.floor(framePaths.length / maxFrames);
    for (let i = 0; i < maxFrames; i++) {
      selectedFrames.push(framePaths[i * step]);
    }
  }

  const descriptions = [];
  for (const framePath of selectedFrames) {
    try {
      const imageBuffer = fs.readFileSync(framePath);
      const base64Image = imageBuffer.toString('base64');

      const requestBody = JSON.stringify({
        model: 'moondream',
        messages: [{
          role: 'user',
          content: 'Transcreva todo o texto visível nesta imagem. Identifique gráficos de SEO, buscas do Google ou telas de sistemas. Responda em português.',
          images: [base64Image]
        }],
        stream: false,
        options: { temperature: 0.2 }
      });

      const result = await new Promise((resolve, reject) => {
        const req = http.request({
          hostname: 'host.docker.internal',
          port: 11434,
          path: '/api/chat',
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(requestBody)
          },
          timeout: 120000
        }, (res) => {
          let respStr = '';
          res.on('data', chunk => respStr += chunk);
          res.on('end', () => {
            try { resolve(JSON.parse(respStr)); }
            catch(e) { resolve({ message: { content: respStr } }); }
          });
        });
        req.on('error', reject);
        req.write(requestBody);
        req.end();
      });

      descriptions.push({
        frame: framePath.split('/').pop(),
        description: result.message?.content || 'Sem descrição'
      });
    } catch (error) {
      descriptions.push({
        frame: framePath.split('/').pop(),
        description: `[Erro: ${error.message}]`
      });
    }
  }

  results.push({
    json: {
      ...data,
      frameDescriptions: descriptions,
      visualSummary: descriptions.map(d => d.description).join('\n---\n')
    }
  });
}

return results;

