// Extração de Conhecimento Estruturado Especializado em SEO via LLM (Qwen2.5:3b)
const http = require('http');

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const isVideo = data.fileType === 'video';

  let context = '';
  if (isVideo) {
    context = `## Vídeo de SEO: ${data.fileName}\n`;
    if (data.transcription) context += `## Transcrição do Áudio:\n${data.transcription}\n\n`;
    if (data.visualSummary) context += `## Telas/Frames Visuais do Vídeo:\n${data.visualSummary}\n\n`;
  } else {
    context = `## Imagem/Post de SEO: ${data.fileName}\n`;
    if (data.visualDescription) context += `## Conteúdo/Texto Transcrito da Imagem:\n${data.visualDescription}\n\n`;
  }

  const systemPrompt = `Você é um Consultor Especialista em SEO (Search Engine Optimization) e Marketing de Conteúdo.
Sua missão principal é extrair um TUTORIAL PASSO A PASSO ULTRA DETALHADO a partir do vídeo/post fornecido, capturando com EXATIDÃO cada clique, menu, ferramenta e tela demonstrada (ex: "Entre no Google Trends", "Clique em Explorar", "Abra o Gemini", "Abra o Semrush", etc.).

NÃO RESUMA OU SINTETIZE DEMAIS. Descreva cada ação prática de forma acionável para que qualquer pessoa possa replicar exatamente os mesmos cliques no próprio negócio.

RETORNE APENAS um JSON válido no seguinte formato (sem texto conversacional adicional):
{
  "titulo_estrategia": "título objetivo da estratégia ou tutorial de SEO",
  "resumo_executivo": "resumo da técnica ensinada em 2 frases",
  "passo_a_passo_detalhado": [
    "Passo 1: [Ação exata] Acesse o site/ferramenta X...",
    "Passo 2: [Clique/Digite] Clique no menu Y ou digite o termo Z...",
    "Passo 3: [Análise/Filtro] Veja os termos de busca e filtre por...",
    "Passo N: ..."
  ],
  "ferramentas_e_telas_utilizadas": ["ex: Google Trends, Gemini, Semrush, Google Search Console"],
  "termos_e_exemplos_usados": ["termos de busca ou palavras-chave usadas como exemplo no vídeo"],
  "aplicacao_no_negocio": "como utilizar essa exata estratégia para ranquear melhor e vender sem depender de anúncios",
  "conceitos_mencionados": ["ex: Long-tail, Volume de busca, Intenção de busca, Dificuldade de palavra-chave"]
}`;

  const requestBody = JSON.stringify({
    model: 'qwen2.5:3b',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: context }
    ],
    stream: false,
    format: 'json',
    options: { temperature: 0.2 }
  });

  try {
    const resData = await new Promise((resolve, reject) => {
      const req = http.request({
        hostname: 'host.docker.internal',
        port: 11434,
        path: '/api/chat',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(requestBody)
        },
        timeout: 180000
      }, (res) => {
        let respStr = '';
        res.on('data', chunk => respStr += chunk);
        res.on('end', () => {
          try { resolve(JSON.parse(respStr)); }
          catch(e) { resolve({ message: { content: respStr } }); }
        });
      });
      req.on('error', reject);
      req.write(requestBody);
      req.end();
    });

    let knowledge = {};
    try {
      knowledge = JSON.parse(resData.message?.content || '{}');
    } catch(e) {
      knowledge = { raw: resData.message?.content };
    }

    results.push({
      json: {
        ...data,
        extractedKnowledge: knowledge
      }
    });
  } catch(err) {
    results.push({
      json: {
        ...data,
        extractedKnowledge: { error: err.message }
      }
    });
  }
}

return results;

// Salvar arquivo JSON final individual para CADA mídia processada
const fs = require('fs');
const path = require('path');

const items = $input.all();
const OUTPUT_DIR = '/data/output';
const OUTPUT_FRAMES_DIR = '/data/output/frames';
if (!fs.existsSync(OUTPUT_DIR)) fs.mkdirSync(OUTPUT_DIR, { recursive: true });
if (!fs.existsSync(OUTPUT_FRAMES_DIR)) fs.mkdirSync(OUTPUT_FRAMES_DIR, { recursive: true });

const savedFiles = [];
for (const item of items) {
  const data = item.json;

  // Se for vídeo e tiver frames, copiar os frames para a pasta de saída persistente
  let savedFramesPaths = [];
  if (data.fileType === 'video' && data.framesDir && fs.existsSync(data.framesDir)) {
    const targetVideoFramesDir = path.join(OUTPUT_FRAMES_DIR, data.baseName);
    if (!fs.existsSync(targetVideoFramesDir)) fs.mkdirSync(targetVideoFramesDir, { recursive: true });

    const files = fs.readdirSync(data.framesDir);
    for (const file of files) {
      const src = path.join(data.framesDir, file);
      const dest = path.join(targetVideoFramesDir, file);
      fs.copyFileSync(src, dest);
      try { fs.chmodSync(dest, 0o666); } catch(e) {}
      savedFramesPaths.push(dest);
    }
    try { fs.chmodSync(targetVideoFramesDir, 0o777); } catch(e) {}
  }

  const document = {
    metadata: {
      source: 'facebook_profile_seo',
      pipeline_version: '2.1.0',
      processed_at: new Date().toISOString()
    },
    source_file: {
      filename: data.fileName,
      type: data.fileType,
      extension: data.extension,
      path: data.filePath,
      duration_seconds: data.durationSeconds || null
    },
    content: {
      transcription: data.transcription || null,
      visual_description: data.fileType === 'video' ? data.visualSummary : data.visualDescription,
      frame_descriptions: data.frameDescriptions || null,
      saved_frame_files: savedFramesPaths
    },
    seo_knowledge: data.extractedKnowledge || {}
  };

  const outputPath = path.join(OUTPUT_DIR, `${data.baseName}.json`);
  fs.writeFileSync(outputPath, JSON.stringify(document, null, 2), 'utf-8');
  try { fs.chmodSync(outputPath, 0o666); } catch(e) {}
  savedFiles.push(outputPath);
}

console.log(`✅ Salvos ${savedFiles.length} arquivos de SEO e frames em ${OUTPUT_DIR}`);
return items.map((item, index) => ({
  json: {
    status: 'success',
    outputFile: savedFiles[index],
    fileName: item.json.fileName
  }
}));
